import sys
import numpy as np

# Allow importing lineage storage module
sys.path.append('storage/verity')

def _fallback_6x6_minus_corners():
    r = 1.0 / 12.0
    xs = [r + k * (2.0 * r) for k in range(6)]
    ys = [r + k * (2.0 * r) for k in range(6)]
    centers = []
    for j in range(6):
        for i in range(6):
            if (i in (0, 5)) and (j in (0, 5)):
                continue
            centers.append([xs[i], ys[j]])
    centers = np.array(centers, dtype=float)
    radii = np.full(centers.shape[0], r, dtype=float) * (1.0 - 1e-12)
    return centers, radii

def construct_packing():
    """
    Reproduce Verity artifact via loader_v5:
    - Load storage/verity/sumr32_best.npz via loader_v5.construct_packing()
    - Return centers unchanged; radii*(1-1e-12)
    - No LP/self-validation/writes; deterministic
    - Fallback to 6x6-minus-corners if import/load fails
    """
    try:
        from loader_v5 import construct_packing as _cp
        return _cp()
    except Exception:
        return _fallback_6x6_minus_corners()
